/* Crisp Animated 6-Frame Side-Profile Run + Jump + Slide + 4B Hover-Coin Sprites */
(function (global) {
  'use strict';
  const RUN_URIS = ['data:image/png;base64,', 'data:image/png;base64,', 'data:image/png;base64,', 'data:image/png;base64,', 'data:image/png;base64,', 'data:image/png;base64,'];
  const OTHER_URIS = {
    jump4A: "data:image/png;base64,",
    slide4A: "data:image/png;base64,",
    full4B: "data:image/png;base64,"
  };

  const sprites = {
    runFrames: [],
    jump4A: null,
    slide4A: null,
    full4B: null
  };

  if (typeof Image === 'function') {
    sprites.runFrames = RUN_URIS.map((uri) => {
      const img = new Image();
      img.src = uri;
      return img;
    });
    Object.keys(OTHER_URIS).forEach((k) => {
      const img = new Image();
      img.src = OTHER_URIS[k];
      sprites[k] = img;
    });
  }

  global.REMO_SPRITES = sprites;
})(window);
